    async function deleteCurrentProject() {
        if (!state.currentProject) return;
        if (!await confirmProjectDelete(state.currentProject.id, state.currentProject.title)) return;
        try {
            await api('/projects/' + state.currentProject.id, { method: 'DELETE' });
            backToProjectList();
            setStatus('Project deleted');
        } catch (err) { setStatus('Error: ' + err.message); }
    }


    /** The brand kits this install has, so a spot can be attached to one. */
    async function loadSettingsBrands() {
        const sel = document.getElementById('settingsBrand');
        if (!sel) return;
        let data;
        try { data = await api('/brands'); } catch (_) { return; }
        const current = (state.currentProject && state.currentProject.brand_id) || '';
        sel.innerHTML = '<option value="">No brand — this is a film</option>'
            + (data.brands || []).map(b =>
                `<option value="${esc(b.id)}"${b.id === current ? ' selected' : ''}>${esc(b.name)}</option>`).join('');
    }

