    /*
     * One Settings section at a time. The section is a class on each card
     * (`set-off`), never `hidden`: the project and delivery cards already use
     * `hidden` for "no project is open", and the two must not overwrite each
     * other. The last section opened is remembered for this browser only.
     */
    const SETTINGS_SECTIONS = ['providers', 'project', 'delivery', 'folder', 'keys', 'backups', 'you', 'graph'];
    function showSettingsSection(id) {
        const want = SETTINGS_SECTIONS.includes(id) ? id : 'providers';
        const page = document.getElementById('page-settings');
        if (!page) return;
        page.querySelectorAll('.set-card[data-set-section]').forEach(c => {
            c.classList.toggle('set-off', c.dataset.setSection !== want);
        });
        page.querySelectorAll('.set-nav-btn').forEach(b => {
            const on = b.dataset.setGo === want;
            b.classList.toggle('on', on);
            if (on) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current');
        });
        // A project section with no project open says why it is empty.
        const shown = [...page.querySelectorAll('.set-card[data-set-section]')]
            .filter(c => c.dataset.setSection === want && !c.classList.contains('hidden'));
        const empty = document.getElementById('setSectionEmpty');
        if (empty) empty.classList.toggle('hidden', shown.length > 0);
        try { localStorage.setItem('fe_settings_section', want); } catch (_) { /* a remembered section is a convenience */ }
    }
    window.showSettingsSection = showSettingsSection;

    function loadSettings() {
        document.getElementById('settingsApiUrl').value = API_BASE;
        let remembered = null;
        try { remembered = localStorage.getItem('fe_settings_section'); } catch (_) { remembered = null; }
        showSettingsSection(remembered || 'providers');
        const pc = document.getElementById('settingsProjectCard');
        if (state.currentProject) {
            pc.classList.remove('hidden');
            document.getElementById('settingsTitle').value = state.currentProject.title || '';
            document.getElementById('settingsLogline').value = state.currentProject.logline || '';
            document.getElementById('settingsStylePreset').value = state.currentProject.style_preset || '';
            // Defaults ON, matching the server: an unset project drafts.
            document.getElementById('settingsVideoDraft').checked =
                state.currentProject.video_draft === undefined || state.currentProject.video_draft === null
                    ? true : !!state.currentProject.video_draft;
            document.getElementById('settingsStyleWarning').innerHTML = '';
            document.getElementById('settingsGenre').value = state.currentProject.genre || '';
            document.getElementById('settingsStatus').value = state.currentProject.status || 'concept';
            // Commercial mode. Blank on a film, which is every project here
            // until somebody says otherwise.
            document.getElementById('settingsClient').value = state.currentProject.client || '';
            document.getElementById('settingsCampaign').value = state.currentProject.campaign || '';
            document.getElementById('settingsTargetDuration').value =
                state.currentProject.target_duration_ms ? (state.currentProject.target_duration_ms / 1000) : '';
            loadSettingsBrands();
        } else {
            pc.classList.add('hidden');
        }
        loadTechnicalSettings();
        // Again, now the project cards know whether they are shown.
        showSettingsSection(remembered || 'providers');
        loadProviders();
        loadAppSettings();
        loadProjectFolder();
    }

    async function loadAppSettings() {
        const el = document.getElementById('settingsAuthor');
        if (!el) return;
        try {
            const res = await api('/settings');
            el.value = (res.settings && res.settings.author) || '';

            const gl = document.getElementById('settingsGridlight');
            if (gl) gl.checked = !!String((res.settings && res.settings.gridlight_enabled) || '').trim();
            // What it would serve, so the consequence of the switch is visible
            // rather than something to be discovered at generation time.
            const serves = document.getElementById('gridlightServes');
            if (serves) {
                try {
                    const cat = await api('/providers');
                    const g = (cat.providers || []).find(x => x.id === 'gridlight');
                    serves.textContent = g
                        ? `Serves ${(g.capabilities || []).join(', ')} when enabled.`
                        : '';
                } catch (_) { serves.textContent = ''; }
            }
        } catch (_) { /* leave it blank; the field says what it is for */ }
    }

    /**
     * Saved on the click, not on a separate Save button.
     *
     * The author field below shares a Save; this does not, because a switch
     * that looks flipped and has not been saved is exactly the state where a
     * director believes the local endpoints are on and every generation quietly
     * resolves somewhere else.
     */
    async function saveGridlightEnabled() {
        const gl = document.getElementById('settingsGridlight');
        if (!gl) return;
        try {
            await api('/settings', { method: 'PUT',
                body: JSON.stringify({ gridlight_enabled: gl.checked ? '1' : '' }) });
            setStatus(gl.checked
                ? 'Local Gridlight endpoints enabled.'
                : 'Local Gridlight endpoints disabled — nothing will resolve to them.');
            if (typeof loadProviders === 'function') loadProviders();
        } catch (err) {
            gl.checked = !gl.checked;   // or the box lies about what was stored
            setStatus('Could not save: ' + err.message);
        }
    }

