    // ── AI Providers (multi-provider layer) ─────────────────────────
    let _providerCatalog = null;
    async function loadProviders() {
        const credEl = document.getElementById('providerCredentials');
        const mapEl = document.getElementById('providerCapabilityMap');
        if (!credEl || !mapEl) return;
        try {
            const catalog = await api('/providers');
            _providerCatalog = catalog;

            // Connection rows: providers that need a key, OAuth connect, or config fields.
            const keyIsSet = p => (!!(p.credentials && (p.credentials.set || p.credentials.connected)) && !(p.credentials && p.credentials.suspect))
                || !!p.enabled;
            /*
             * ONE TILE PER ACCOUNT, named for the account and listing every
             * capability its key covers. An adapter that runs on another's key
             * (MuAPI images on the key stored for Seedance) folds into that tile
             * rather than showing a second box for the same key.
             */
            const all = (catalog.providers || []).filter(p => p.requiresKey || p.connection);
            const ids = new Set(all.map(p => p.id));
            const needsSetup = all.filter(p => !(p.sharesKeyWith && ids.has(p.sharesKeyWith)))
                .map(p => {
                    const riders = all.filter(r => r.sharesKeyWith === p.id);
                    if (!riders.length) return p;
                    const caps = [...new Set([...(p.capabilities || []), ...riders.flatMap(r => r.capabilities || [])])];
                    return { ...p, capabilities: caps };
                })
                // Set ones first, so what is missing is the second thing you read, not lost in the middle.
                .sort((a, b) => (keyIsSet(b) - keyIsSet(a)) || String(a.account || a.label).localeCompare(String(b.account || b.label)));
            const keyName = p => p.account || String(p.label || p.id).replace(/\s*\(.*\)\s*$/, '');
            const countEl = document.getElementById('providerKeyCount');
            if (countEl) countEl.textContent = needsSetup.length ? `${needsSetup.filter(keyIsSet).length} of ${needsSetup.length} set` : '';
            // What a key is FOR, in the words the provider section uses.
            const CAP_WORDS = { llm: 'Writing', image: 'Image', video: 'Video', music: 'Music', voice: 'Voice', sfx: 'Effects',
                ambient: 'Ambience', lipsync: 'Lip-sync', post: 'Upscale', model3d: '3D', world: 'World' };
            const serves = p => (p.capabilities || []).map(c => CAP_WORDS[c] || c).join(' · ');
            credEl.className = 'set-keys';
            credEl.innerHTML = needsSetup.length ? needsSetup.map(p => {
                const c = p.credentials || { set: false, fields: {} };
                const conn = p.connection || null;
                const instr = conn && conn.instructions ? '<p class="text-sm text-muted" style="margin:4px 0 8px;">' + esc(conn.instructions) + '</p>' : '';

                // 1) OAuth "Connect" providers (any adapter declaring connection.oauth).
                if (conn && conn.oauth) {
                    const connected = c.connected;
                    const status = connected ? '<span class="set-pill ok">connected</span>' : '<span class="set-pill">not connected</span>';
                    // Optional: existing-OAuth-client fields (to skip dynamic registration).
                    const optFields = (Array.isArray(conn.fields) && conn.fields.length) ? `
                        <details style="margin-top:8px;">
                            <summary class="text-sm text-muted" style="cursor:pointer;">Advanced: use an existing OAuth client</summary>
                            <div style="margin-top:6px;">
                                ${conn.fields.map(f => {
                                    const isSet = c.fields && c.fields[f.key];
                                    return '<div style="margin-bottom:6px;"><label class="text-sm">' + esc(f.label || f.key) + (isSet ? ' <span class="tag" style="background:var(--gl-success,#166534);">set</span>' : '') + '</label><input type="' + (f.type === 'password' ? 'password' : 'text') + '" id="provfield-' + esc(p.id) + '-' + esc(f.key) + '" placeholder="' + (isSet ? '•••••• (leave blank to keep)' : '') + '" style="width:100%;"></div>';
                                }).join('')}
                                <button class="btn btn-secondary btn-sm" onclick="saveProviderFields('${esc(p.id)}')">Save client</button>
                            </div>
                        </details>` : '';
                    return `<div class="set-key">
                        <label>${esc(keyName(p))} ${status}</label>${serves(p) ? `<div class="set-key-serves">${esc(serves(p))}</div>` : ''}${instr}
                        <div style="display:flex;gap:6px;flex-wrap:wrap;">
                            <button class="btn btn-primary btn-sm" onclick="connectProviderOAuth('${esc(p.id)}')">${connected ? 'Reconnect' : 'Connect ' + esc(p.label.split(' ')[0])}</button>
                            ${connected ? '<button class="btn btn-danger btn-sm" onclick="disconnectProvider(\'' + esc(p.id) + '\')">Disconnect</button>' : ''}
                            <button class="btn btn-secondary btn-sm" onclick="releaseRegisteredClient('${esc(p.id)}')"
                                    data-tooltip="Delete the OAuth client Film Engine registered with this provider, freeing a registration slot. Use if connecting fails with a registration limit."
                                    data-tooltip-pos="bottom">Release registered client</button>
                        </div>
                        ${optFields}
                    </div>`;
                }

                // 2) Multi-field providers (adapters declaring connection.fields, e.g. client_id/secret).
                if (conn && Array.isArray(conn.fields) && conn.fields.length) {
                    const fieldsHtml = conn.fields.map(f => {
                        const isSet = c.fields && c.fields[f.key];
                        const badge = isSet ? ' <span class="tag" style="background:var(--gl-success,#166534);">set</span>' : '';
                        return `<div style="margin-bottom:6px;">
                            <label class="text-sm">${esc(f.label || f.key)}${badge}</label>
                            <input type="${f.type === 'password' ? 'password' : 'text'}" id="provfield-${esc(p.id)}-${esc(f.key)}" placeholder="${isSet ? '•••••• (leave blank to keep)' : esc(f.placeholder || '')}" style="width:100%;">
                        </div>`;
                    }).join('');
                    return `<div class="set-key">
                        <label>${esc(keyName(p))}${p.enabled ? ' <span class="set-pill ok">set</span>' : ''}</label>${serves(p) ? `<div class="set-key-serves">${esc(serves(p))}</div>` : ''}${instr}${fieldsHtml}
                        <div class="set-key-btns">
                            ${conn.helpUrl ? '<a class="btn btn-secondary btn-sm" href="' + esc(conn.helpUrl) + '" target="_blank" rel="noopener">Get key &#8599;</a>' : ''}
                            <button class="btn btn-secondary btn-sm" onclick="saveProviderFields('${esc(p.id)}')">Save</button>
                            ${p.checkable ? `<button class="btn btn-secondary btn-sm" onclick="checkProviderKey('${esc(p.id)}', this)" title="Asks the provider whether the key works. Free: nothing is generated.">Check key</button>` : ''}
                        </div>
                        <div class="text-sm" id="provcheck-${esc(p.id)}"></div>
                    </div>`;
                }

                // 3) Single API-key providers. One compact row each: name and
                // state, the key box, the buttons. A stored placeholder must not
                // wear the same green badge as a working key: "set ••••k" is
                // what let six providers look configured until a 401 arrived.
                const status = c.suspect
                    ? '<span class="set-pill warn">too short to be a key</span>'
                    : c.set ? '<span class="set-pill ok">set ••••' + esc(c.last4 || '') + '</span>'
                    // Runs on a key stored for another adapter of the same account (MuAPI images use Seedance's).
                    : p.enabled ? '<span class="set-pill ok" title="This provider runs on a key stored for another provider of the same account.">ready · shared key</span>'
                    : '<span class="set-pill">not set</span>';
                const helpUrl = conn && conn.helpUrl;
                const getKeyBtn = helpUrl ? '<a class="btn btn-secondary btn-sm" href="' + esc(helpUrl) + '" target="_blank" rel="noopener" title="' + esc((conn && conn.instructions) || 'Opens the provider\'s key page') + '">Get key &#8599;</a>' : '';
                return `<div class="set-key">
                    <label title="${esc((conn && conn.instructions) || '')}">${esc(keyName(p))} ${status}</label>
                    ${serves(p) ? `<div class="set-key-serves">${esc(serves(p))}</div>` : ''}
                    <input type="password" id="provkey-${esc(p.id)}" placeholder="${c.set ? 'Replace key' : 'Enter API key'}">
                    <div class="set-key-btns">
                        ${getKeyBtn}
                        <button class="btn btn-secondary btn-sm" onclick="saveProviderKey('${esc(p.id)}')">Save</button>
                        ${c.set ? '<button class="btn btn-danger btn-sm" onclick="clearProviderKey(\'' + esc(p.id) + '\')">Clear</button>' : ''}
                    </div>
                </div>`;
            }).join('') : '<p class="text-sm text-muted">No providers require setup. (Gridlight uses a server-side env key.)</p>';

            // Per-capability provider selectors (needs a current project).
            if (!state.currentProject) {
                mapEl.innerHTML = '<div class="set-empty-note"><strong>No project is open.</strong> Which provider and model make each kind of thing is chosen per project: open one from the project list, then come back here. API keys, below in the list, work without a project.</div>';
                return;
            }
            const proj = await api('/projects/' + state.currentProject.id + '/providers');
            const caps = proj.capabilities || [];
            const supportsCap = (cap) => (catalog.providers || []).filter(p => (p.capabilities || []).includes(cap));
            const capabilityLabels = {
                llm: 'Writing',
                image: 'Image',
                video: 'Video',
                music: 'Music',
                voice: 'Voice',
                sfx: 'Sound effects',
                ambient: 'Ambience',
                lipsync: 'Lip-sync',
                post: 'Upscale and finish',
                model3d: '3D model',
                world: 'World',
            };
            const capabilityHelp = {
                llm: 'Scene cards, descriptions and analysis.',
                image: 'Storyboard frames and reference plates.',
                model3d: 'Characters and props as meshes.',
                world: 'A location as a navigable world.',
                video: 'A clip from each shot\'s board frame.',
                post: 'Clips brought to the delivery size.',
                lipsync: 'Mouths matched to the dialogue.',
                voice: 'Each character\'s lines.',
                music: 'Score cues.',
                sfx: 'One-shot effects on a shot.',
                ambient: 'A scene\'s room tone, looped.',
            };
            /*
             * GROUPED BY WHAT THEY MAKE, so a director finds "the video one"
             * without reading eleven rows. A capability not named here still
             * lands, under Other: a new one must never be dropped from the page.
             */
            const CAP_GROUPS = [
                { title: 'Pictures', note: 'Frames, plates, and places a camera can stand in', caps: ['image', 'model3d', 'world'] },
                { title: 'Motion', note: 'Clips, and what finishes them', caps: ['video', 'post', 'lipsync'] },
                { title: 'Sound', note: 'Dialogue, score, effects and room tone', caps: ['voice', 'music', 'sfx', 'ambient'] },
                { title: 'Writing', note: 'Scene cards, descriptions, analysis', caps: ['llm'] },
            ];
            /*
             * QUALITY FIRST, PROVIDER SECOND.
             *
             * A director chooses how good the frame needs to be, not which
             * company makes it — so the three tiers lead and the per-capability
             * provider selectors move into Advanced. When a better model ships
             * the routing table changes and this page does not.
             *
             * Each tier still says what it would ACTUALLY use here, quietly:
             * a tier whose preferred provider holds no key on this install
             * falls through, and hiding that would promise a model we cannot run.
             */
            const tiers = proj.image_tiers || [];
            const currentTier = proj.image_quality || 'standard';
            // Image quality: the three tiers as one row of choices, saved on the
            // click. Each says what it would ACTUALLY use here, so a tier whose
            // preferred provider holds no key does not promise a model we
            // cannot run.
            const tierHtml = !tiers.length ? '' : `
                <h4 class="set-h4">Image quality <span>&mdash; chooses the image provider and model when neither is pinned below</span></h4>
                <div class="set-tiers" title="Image quality: the tier chooses the provider and model when neither is pinned below.">
                    ${tiers.map(t => `
                        <button type="button" class="btn ${t.id === currentTier ? '' : 'btn-secondary'} fe-tier"
                            onclick="pickImageTier('${esc(t.id)}')" id="tierbtn-${esc(t.id)}"
                            style="${t.available ? '' : 'opacity:.55;'}" title="${esc(t.why || '')} ${esc(t.reason || '')}">
                            <div style="font-weight:600;font-size:13px;">${esc(t.label)}</div>
                            <div class="text-sm" style="opacity:.75;font-weight:400;">${t.usd_per_image != null ? '$' + t.usd_per_image.toFixed(3) + ' per image' : esc(t.reason || '')}</div>
                        </button>`).join('')}
                    <button type="button" class="btn ${currentTier === 'auto' ? '' : 'btn-secondary'} fe-tier" onclick="pickImageTier('auto')"
                        title="Auto reads each request and lifts to Precision when a frame has to reconcile several references or edit an existing shot.">
                        <div style="font-weight:600;font-size:13px;">${currentTier === 'auto' ? '✓ ' : ''}Auto</div>
                        <div class="text-sm" style="opacity:.75;font-weight:400;">picks per request</div>
                    </button>
                </div>
                <input type="hidden" id="provImageQuality" value="${esc(currentTier)}">`;

            // Which project these controls were built from — read by
            // saveProviderConfig before it writes anything.
            const stamp = `<input type="hidden" id="providerPanelProject" value="${esc(proj.project_id || (state.currentProject && state.currentProject.id) || '')}">`;

            /*
             * WHO CHOSE THIS is said on each card's status line: "Automatic" and a
             * pinned provider can resolve to the SAME vendor; only who chose it
             * differs, and a lost pin went on billing another company's account
             * until its billing refused.
             */
            _providerModelMenus = {};
            const rows = caps.map(cap => {
                const opts = supportsCap(cap);
                if (opts.length === 0) return null;
                // What was PINNED, which is not the same as what resolved.
                const pinned = (proj.config && proj.config[cap]) || '';
                const gen = (proj.generation || {})[cap];
                // Every provider's own model list for THIS capability, so the
                // model menu follows the provider picked beside it.
                _providerModelMenus[cap] = {};
                ((gen && gen.providers) || []).forEach(p => { _providerModelMenus[cap][p.id] = { models: p.models || [], default_model: p.default_model || null }; });
                const pinnedModel = (proj.config && proj.config[cap + '_model']) || '';
                // One line saying who runs this and whether it can: the vendor's key is the usual gap.
                const effectiveId = (proj.effective && proj.effective[cap]) || '';
                const eff = (catalog.providers || []).find(p => p.id === effectiveId);
                // `enabled` is the engine's own answer: MuAPI's image adapter runs on the
                // key stored for Seedance, so "its own key is empty" is not "cannot run".
                const noKey = eff && eff.requiresKey && !eff.enabled;
                const r = (proj.resolution || {})[cap];
                const fellThrough = !pinned && r && r.provider && !r.explicit;
                const vendor = esc((eff && eff.label) || effectiveId);
                const who = pinned ? 'Pinned for this project' : (effectiveId ? `Automatic → ${vendor}` : 'Automatic');
                const stateLine = noKey
                    ? `<div class="set-cap-state warn">${who} · no key for ${vendor} — add it under API keys</div>`
                    : fellThrough
                        ? `<div class="set-cap-state warn" title="${esc(r.note || '')}">Nobody picked this: it falls to ${vendor}, and spend goes there. Pick a provider to pin it.</div>`
                        : `<div class="set-cap-state">${who}</div>`;
                return { cap, html: `<div class="set-cap">
                    <div><div class="set-cap-name">${esc(capabilityLabels[cap] || cap)}</div>${capabilityHelp[cap] ? '<div class="set-cap-note">' + esc(capabilityHelp[cap]) + '</div>' : ''}</div>
                    <label>Provider
                        <select id="provcap-${esc(cap)}" onchange="refreshModelMenu('${esc(cap)}')">
                            <option value=""${pinned ? '' : ' selected'}>Automatic${cap === 'image' ? ' (quality tier)' : ''}${proj.effective && proj.effective[cap] ? ' → ' + esc(proj.effective[cap]) : ''}</option>
                            ${opts.map(o => '<option value="' + esc(o.id) + '"' + (o.id === pinned ? ' selected' : '') + '>' + esc(o.label) + '</option>').join('')}
                        </select>
                    </label>
                    ${cap === 'llm'
                        ? '<div class="set-cap-note">The connected agent (Claude or ChatGPT Desktop) is the model.</div>'
                        : `<label>Model<select id="provmodel-${esc(cap)}" data-pinned="${esc(pinnedModel)}" data-effective="${esc((proj.effective && proj.effective[cap]) || '')}"></select></label>`}
                    ${stateLine}
                </div>` };
            }).filter(Boolean);

            const byCap = new Map(rows.map(r => [r.cap, r.html]));
            const named = new Set(CAP_GROUPS.flatMap(g => g.caps));
            const groups = CAP_GROUPS.concat([{ title: 'Other', note: '', caps: rows.map(r => r.cap).filter(c => !named.has(c)) }])
                .map(g => ({ ...g, cards: g.caps.filter(c => byCap.has(c)).map(c => byCap.get(c)) }))
                .filter(g => g.cards.length);
            mapEl.innerHTML = tierHtml + stamp + groups.map(g => `
                <section class="set-group">
                    <div><h4 class="set-group-h">${esc(g.title)}</h4>${g.note ? `<p class="set-group-note">${esc(g.note)}</p>` : ''}</div>
                    <div class="set-caps">${g.cards.join('')}</div>
                </section>`).join('') + `
                ${(proj.config && proj.config.image_model) ? '<div class="set-cap-note" style="margin-top:6px;">A pinned image model overrides the quality tier; set it back to Default to let quality decide again.</div>' : ''}`;
            caps.forEach(cap => { if (document.getElementById('provmodel-' + cap)) refreshModelMenu(cap); });
        } catch (err) { credEl.innerHTML = '<p class="text-sm text-muted">Providers unavailable: ' + esc(err.message) + '</p>'; }
    }

    /*
     * THE MODEL MENU FOLLOWS THE PROVIDER.
     *
     * A model only means anything relative to a provider, so the menu lists
     * the models of whichever provider is picked beside it — or, on Automatic,
     * of the provider that would actually run. "Default" leaves the choice to
     * the provider (or, for images, the quality tier). A pinned model the
     * provider does not offer is shown and flagged rather than dropped, so a
     * saved choice never disappears silently.
     */
    let _providerModelMenus = {};
    function refreshModelMenu(cap) {
        const sel = document.getElementById('provmodel-' + cap);
        const prov = document.getElementById('provcap-' + cap);
        if (!sel || !prov) return;
        const pid = prov.value || sel.dataset.effective || '';
        const menu = (_providerModelMenus[cap] || {})[pid] || { models: [] };
        // After the first draw a provider change keeps the model only if the
        // new provider offers it; the saved pin is shown (flagged) once, so a
        // choice the provider no longer offers is visible rather than lost.
        const first = !sel.dataset.rendered;
        let pinned = first ? (sel.dataset.pinned || '') : (sel.value || '');
        const models = menu.models || [];
        let known = models.some(m => m.id === pinned);
        if (!first && pinned && !known) { pinned = ''; known = false; }
        sel.dataset.rendered = '1';
        const deflt = cap === 'image' ? 'Default (quality tier)' : (menu.default_model ? `Default (${menu.default_model})` : 'Default');
        sel.innerHTML = `<option value="">${esc(deflt)}</option>`
            + models.map(m => `<option value="${esc(m.id)}"${m.id === pinned ? ' selected' : ''}>${esc(m.label && m.label !== m.id ? m.label + ' · ' + m.id : m.id)}</option>`).join('')
            + (pinned && !known ? `<option value="${esc(pinned)}" selected>${esc(pinned)} (not offered by ${esc(pid || 'this provider')})</option>` : '');
        sel.disabled = !models.length && !pinned;
        sel.title = models.length ? '' : `${pid || 'This provider'} offers no model choice for this.`;
    }

    function pickImageTier(tier) {
        const hidden = document.getElementById('provImageQuality');
        if (hidden) hidden.value = tier;
        // Saved immediately rather than on a separate button: choosing a
        // quality IS the action, and a picker that needs a second click to
        // take effect is one people believe they have already used.
        saveProviderConfig();
    }

    async function saveProviderKey(providerId) {
        const input = document.getElementById('provkey-' + providerId);
        const key = input ? input.value.trim() : '';
        if (!key) { setStatus('Enter an API key first'); return; }
        try {
            await api('/providers/' + providerId + '/credentials', { method: 'PUT', body: JSON.stringify({ api_key: key }) });
            setStatus(providerId + ' key saved');
            loadProviders();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    // Save multi-field connection credentials (adapters declaring connection.fields).
    async function saveProviderFields(providerId) {
        const prov = (_providerCatalog && _providerCatalog.providers || []).find(p => p.id === providerId);
        const fieldDefs = (prov && prov.connection && prov.connection.fields) || [];
        const fields = {};
        fieldDefs.forEach(f => {
            const el = document.getElementById('provfield-' + providerId + '-' + f.key);
            if (el && el.value.trim()) fields[f.key] = el.value.trim();
        });
        if (Object.keys(fields).length === 0) { setStatus('Nothing to save'); return; }
        try {
            await api('/providers/' + providerId + '/credentials', { method: 'PUT', body: JSON.stringify({ fields }) });
            setStatus(providerId + ' settings saved');
            loadProviders();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    /** Is the stored key right? Free: the provider is asked something that costs nothing. */
    async function checkProviderKey(providerId, btn) {
        const out = document.getElementById('provcheck-' + providerId);
        if (btn) btn.disabled = true;
        if (out) out.textContent = 'Checking…';
        try {
            const r = await api('/providers/' + providerId + '/check');
            if (out) { out.textContent = '✓ ' + (r.note || 'The key works.'); out.style.color = 'var(--gl-success, #22c55e)'; }
        } catch (err) {
            if (out) { out.textContent = '✗ ' + err.message; out.style.color = 'var(--gl-danger, #ef4444)'; }
        } finally { if (btn) btn.disabled = false; }
    }

    // OAuth connect: open the authorize URL in a popup and
    // refresh once the backend callback posts back.
    async function connectProviderOAuth(providerId) {
        try {
            setStatus('Connecting ' + providerId + '…');
            const res = await api('/providers/' + providerId + '/connect');
            if (!res.authorize_url) { setStatus('Connect failed: no authorize URL'); return; }
            const popup = window.open(res.authorize_url, 'provider-oauth', 'width=520,height=680');
            const onMsg = (ev) => {
                if (ev.data && ev.data.type === 'provider-oauth') {
                    window.removeEventListener('message', onMsg);
                    setStatus(ev.data.ok ? providerId + ' connected' : providerId + ' connect failed');
                    setTimeout(loadProviders, 500);
                }
            };
            window.addEventListener('message', onMsg);
            // Fallback: poll for popup close, then refresh.
            const iv = setInterval(() => { if (popup && popup.closed) { clearInterval(iv); loadProviders(); } }, 1500);
        } catch (err) { setStatus('Connect error: ' + err.message); }
    }

    async function disconnectProvider(providerId) {
        try {
            await api('/providers/' + providerId + '/disconnect', { method: 'POST', body: JSON.stringify({}) });
            setStatus(providerId + ' disconnected');
            loadProviders();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    /**
     * Delete the OAuth client Film Engine registered with this provider.
     *
     * Different from Disconnect: disconnecting forgets our copy but leaves the
     * client registered on the provider's side, still occupying one of the
     * account's limited slots. This is what actually frees a slot when connect
     * fails with a registration cap.
     */
    async function releaseRegisteredClient(providerId) {
        if (!confirm('Delete the OAuth client Film Engine registered with ' + providerId + '?\n\nThis frees a registration slot at the provider. You will need to connect again afterwards.')) return;
        try {
            const res = await api('/providers/' + providerId + '/release-client', { method: 'POST', body: JSON.stringify({}) });
            setStatus(res.message || (providerId + ' client released'));
            loadProviders();
        } catch (err) {
            setStatus('Error: ' + err.message);
        }
    }

    async function clearProviderKey(providerId) {
        try {
            await api('/providers/' + providerId + '/credentials', { method: 'DELETE' });
            setStatus(providerId + ' key cleared');
            loadProviders();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function saveProviderConfig() {
        if (!state.currentProject) { setStatus('Open a project first'); return; }
        /*
         * A PANEL RENDERED FOR ANOTHER PROJECT MUST NOT BE SAVED TO THIS ONE.
         *
         * Every control here is read by id, so the selects survive a project
         * switch holding the previous film's answers — and a tier click saves
         * immediately, with no second confirmation. Writing those answers onto
         * the project now open is how a deliberate choice disappears without
         * anybody touching the control that held it.
         */
        const renderedFor = document.getElementById('providerPanelProject');
        if (renderedFor && renderedFor.value && renderedFor.value !== state.currentProject.id) {
            setStatus('Provider settings were showing another project — reloading them');
            loadProviders();
            return;
        }

        const caps = (_providerCatalog && _providerCatalog.capabilities) || [];
        const config = {};
        caps.forEach(cap => {
            const sel = document.getElementById('provcap-' + cap);
            if (!sel) return;
            /*
             * null means "unpin this", and it is only said when the control
             * genuinely offers Automatic and the user is on it. A blank sent as
             * "" means "no opinion" and the server keeps what it has — because
             * a blank control in a bulk payload is far more often a render that
             * has not caught up than a decision to clear something.
             */
            config[cap] = sel.value ? sel.value
                : (sel.options.length > 1 ? null : '');
        });
        // Carried explicitly: the route keeps only keys it recognises, so a
        // tier left out here would save as nothing and the setting would look
        // like it worked while reaching no generation.
        const q = document.getElementById('provImageQuality');
        if (q && q.value) config.image_quality = q.value;
        // A model per capability. Sent for every capability that has a menu,
        // blank meaning "stop pinning": the route checks each against the
        // provider that would run it and refuses a model it does not offer.
        caps.forEach(cap => {
            const ms = document.getElementById('provmodel-' + cap);
            if (ms && !ms.disabled) config[cap + '_model'] = ms.value.trim();
        });
        try {
            await api('/projects/' + state.currentProject.id + '/providers', { method: 'PUT', body: JSON.stringify({ config }) });
            setStatus('Provider settings saved');
            loadProviders();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    function saveSettings() {
        const url = document.getElementById('settingsApiUrl').value.trim().replace(/\/+$/, '');
        if (url) {
            API_BASE = url;
            feStore.set('film_api_url', url);
            setStatus('API URL saved: ' + url);
            checkHealth();
        }
    }

    function resetSettings() {
        API_BASE = DEFAULT_API_BASE;
        feStore.remove('film_api_url');
        document.getElementById('settingsApiUrl').value = DEFAULT_API_BASE;
        setStatus('Settings reset');
        checkHealth();
    }

    async function saveProjectSettings() {
        if (!state.currentProject) return;
        const data = {
            title: document.getElementById('settingsTitle').value.trim(),
            logline: document.getElementById('settingsLogline').value.trim(),
            genre: document.getElementById('settingsGenre').value.trim(),
            status: document.getElementById('settingsStatus').value,
            style_preset: document.getElementById('settingsStylePreset').value.trim(),
            video_draft: document.getElementById('settingsVideoDraft').checked ? 1 : 0,
            client: document.getElementById('settingsClient').value.trim(),
            campaign: document.getElementById('settingsCampaign').value.trim(),
            // Typed in seconds and stored in milliseconds, which is how a
            // runtime is read and how everything else here measures.
            target_duration_ms: Math.round((Number(document.getElementById('settingsTargetDuration').value) || 0) * 1000),
            brand_id: document.getElementById('settingsBrand').value,
        };
        try {
            const p = await api('/projects/' + state.currentProject.id, { method: 'PUT', body: JSON.stringify(data) });
            state.currentProject = { ...state.currentProject, ...p };
            document.getElementById('navProjectName').textContent = state.currentProject.title;
            paintProjectType(state.currentProject);
            setStatusDot(state.currentProject.status);

            /*
             * The route already runs the subject check on every style write and
             * returns `style_warning`. It WARNS rather than blocks, on the
             * precedent previs set — a creature film may genuinely want a
             * creature in every frame, and refusing the save would overrule the
             * author. But a warning nobody renders is a warning that does not
             * exist, so it is shown beside the field it is about.
             */
            const warn = document.getElementById('settingsStyleWarning');
            // `style_warning` is {subjects, detail}, not a string — rendering it
            // directly prints [object Object], which is a warning that teaches
            // the reader to ignore warnings.
            warn.innerHTML = p.style_warning
                ? '<p class="text-sm" style="margin-top:6px;color:var(--gl-warning);line-height:1.5;">'
                  + esc(p.style_warning.detail
                        || ('This style names a subject: ' + (p.style_warning.subjects || []).join(', ')))
                  + '</p>'
                : '';
            setStatus('Project updated');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    // ══════════════════════════════════════════════════════════════
    // FILM-138: TECHNICAL PROJECT SETTINGS
    // ══════════════════════════════════════════════════════════════
    const DELIVERY_PRESETS = {
        theatrical_dcp: { aspect_ratio: '2.39:1', target_resolution: '4096x2160', target_fps: 24, color_space: 'DCI-P3' },
        imax: { aspect_ratio: '1.43:1', target_resolution: '5632x4096', target_fps: 24, color_space: 'DCI-P3' },
        streaming_hd: { aspect_ratio: '16:9', target_resolution: '1920x1080', target_fps: 24, color_space: 'Rec.709' },
        streaming_4k: { aspect_ratio: '16:9', target_resolution: '3840x2160', target_fps: 24, color_space: 'Rec.709' },
        social_media: { aspect_ratio: '9:16', target_resolution: '1080x1920', target_fps: 30, color_space: 'sRGB' },
        broadcast: { aspect_ratio: '16:9', target_resolution: '1920x1080', target_fps: 29.97, color_space: 'Rec.709' },
    };

    /*
     * A preset is applied by the SERVER, which writes every field it carries —
     * the codec and audio layout included — so the page and the API cannot
     * disagree about what a preset is. The local table below is the fallback
     * for a page with no project open.
     */
    async function applyDeliveryPreset(name) {
        if (name && state.currentProject) {
            try {
                const r = await api('/projects/' + state.currentProject.id + '/settings/preset', { method: 'POST', body: JSON.stringify({ preset: name }) });
                if (r && r.project) { state.currentProject = { ...state.currentProject, ...r.project }; loadTechnicalSettings(); return; }
            } catch (err) { setStatus('Error: ' + err.message); }
        }
        const preset = DELIVERY_PRESETS[name];
        if (!preset) return;
        document.getElementById('settingsAspectRatio').value = preset.aspect_ratio;
        document.getElementById('settingsResolution').value = preset.target_resolution;
        document.getElementById('settingsFps').value = String(preset.target_fps);
        document.getElementById('settingsColorSpace').value = preset.color_space;
        onAspectRatioChange(preset.aspect_ratio);
    }

    function onAspectRatioChange(val) {
        document.getElementById('customAspectGroup').style.display = val === 'custom' ? '' : 'none';
        updateAspectPreview(val === 'custom' ? document.getElementById('settingsAspectCustom').value : val);
    }

    function updateAspectPreview(ratio) {
        const box = document.getElementById('aspectPreview');
        const label = document.getElementById('aspectPreviewLabel');
        if (!box) return;
        let w = 200, h = 112;
        const parsed = parseAspectRatio(ratio);
        if (parsed > 0) {
            if (parsed >= 1) { w = 200; h = Math.round(200 / parsed); }
            else { h = 200; w = Math.round(200 * parsed); }
        }
        box.style.width = w + 'px';
        box.style.height = Math.max(h, 30) + 'px';
        label.textContent = ratio || '16:9';
    }

    function parseAspectRatio(str) {
        if (!str) return 16/9;
        const m1 = str.match(/^(\d+(?:\.\d+)?):(\d+(?:\.\d+)?)$/);
        if (m1) return parseFloat(m1[1]) / parseFloat(m1[2]);
        return 16/9;
    }

    function loadTechnicalSettings() {
        const tc = document.getElementById('settingsTechnicalCard');
        if (!state.currentProject) { tc.classList.add('hidden'); return; }
        tc.classList.remove('hidden');
        const p = state.currentProject;
        if (p.aspect_ratio) document.getElementById('settingsAspectRatio').value = p.aspect_ratio;
        if (p.aspect_ratio_custom) document.getElementById('settingsAspectCustom').value = p.aspect_ratio_custom;
        if (p.target_resolution) document.getElementById('settingsResolution').value = p.target_resolution;
        if (p.target_fps) document.getElementById('settingsFps').value = String(p.target_fps);
        if (p.color_space) document.getElementById('settingsColorSpace').value = p.color_space;
        if (p.delivery_format) document.getElementById('settingsDeliveryPreset').value = p.delivery_format;
        if (p.timecode_start) document.getElementById('settingsTimecodeStart').value = p.timecode_start;
        document.getElementById('settingsDeliveryCodec').value = p.delivery_codec || '';
        document.getElementById('settingsDeliveryAudio').value = String(p.delivery_audio_channels || 2);
        document.getElementById('settingsDraftVideo').checked = Number(p.draft_video) === 1;
        onAspectRatioChange(document.getElementById('settingsAspectRatio').value);
    }

    async function saveTechnicalSettings() {
        if (!state.currentProject) return;
        const ar = document.getElementById('settingsAspectRatio').value;
        const data = {
            aspect_ratio: ar,
            aspect_ratio_custom: ar === 'custom' ? document.getElementById('settingsAspectCustom').value.trim() : '',
            target_resolution: document.getElementById('settingsResolution').value,
            target_fps: parseFloat(document.getElementById('settingsFps').value),
            color_space: document.getElementById('settingsColorSpace').value,
            delivery_format: document.getElementById('settingsDeliveryPreset').value,
            timecode_start: document.getElementById('settingsTimecodeStart').value.trim() || '01:00:00:00',
            delivery_codec: document.getElementById('settingsDeliveryCodec').value,
            delivery_audio_channels: Number(document.getElementById('settingsDeliveryAudio').value) || 2,
            video_draft: document.getElementById('settingsDraftVideo').checked,
        };
        try {
            const p = await api('/projects/' + state.currentProject.id, { method: 'PUT', body: JSON.stringify(data) });
            state.currentProject = { ...state.currentProject, ...p };
            setStatus('Technical settings saved');
        } catch (err) { setStatus('Error: ' + err.message); }
    }
